def vowels_count(s):
    vowels = "aeiouAEIOU"
    count = sum(1 for c in s if c in vowels)
    if s[-1] in "yY":
        count += 1
    return count

def vowels_count(s):
    vowels = "aeiou"
    count = sum(1 for char in s.lower() if char in vowels)
    if s and s[-1].lower() == 'y':
        count += 1
    return count

